// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE, LogFile} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;
    LogFile logFile;

    function setUp() public {
        c = new BANK_SAFE();
        logFile = new LogFile();
        c.SetLogFile(address(logFile));
        c.Initialized();
    }

    function testFuzz_property(uint256 depositAmount, uint256 collectAmount) public {
        depositAmount = bound(depositAmount, 0, type(uint128).max);
        collectAmount = bound(collectAmount, 0, depositAmount);

        RecordingReceiver receiver = new RecordingReceiver();
        vm.deal(address(receiver), depositAmount);

        vm.prank(address(receiver));
        c.Deposit{value: depositAmount}();

        uint256 balanceBefore = c.balances(address(receiver));
        require(balanceBefore == depositAmount, "setup deposit mismatch");
        require(balanceBefore >= collectAmount, "collectAmount too large");

        bool ok;
        vm.prank(address(receiver));
        try c.Collect(collectAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok || receiver.lastValue() == collectAmount);
    }
}

contract RecordingReceiver {
    uint256 public lastValue;

    receive() external payable {
        lastValue = msg.value;
    }
}
